import sys

def solve(n, grid):
    def is_valid(x, y, color):
        count = 0
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == color:
                count += 1
        return count == 2

    def dfs(x, y, color):
        stack = [(x, y)]
        visited.add((x, y))
        grid[x] = grid[x][:y] + color + grid[x][y+1:]
        while stack:
            cx, cy = stack.pop()
            for dx, dy in [(-1, 0), (1,0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                    if grid[nx][ny] == '.':
                        grid[nx] = grid[nx][:ny] + ('S' if color == 'G' else 'G') + grid[nx][ny+1:]
                        stack.append((nx, ny))
                        visited.add((nx, ny))
                    elif grid[nx][ny] == color:
                        if not is_valid(nx, ny, color):
                            return False
        return True

    visited = set()
    colors = {'S': 'G', 'G': 'S'}
    for i in range(n):
        for j in range(n):
            if grid[i][j] != '.' and not is_valid(i, j, grid[i][j]):
                print("NONE")
                return
            if grid[i][j] == '.':
                for color in 'SG':
                    if (i, j) not in visited:
                        new_grid = grid[:]
                        if dfs(i, j, color):
                            temp_visited = visited.copy()
                            if dfs(i, j, colors[color]):
                                print("MULTIPLE")
                                return
                            visited = temp_visited
                        else:
                            grid = new_grid
    print("UNIQUE")
    for line in grid:
        print(line)

n = int(sys.stdin.readline().strip())
grid = [sys.stdin.readline().strip() for _ in range(n)]
solve(n, grid)
